import React from 'react';
import { Alert, Button, Stack, Typography } from '@mui/material';
import { VerifiedUser as VerifiedIcon } from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';

export interface GetVerifiedBannerProps {
  isVerified: boolean;
  status?: string;
  compact?: boolean;
}

const GetVerifiedBanner: React.FC<GetVerifiedBannerProps> = ({
  isVerified,
  status,
  compact = false,
}) => {
  if (isVerified || status === 'verified') {
    return (
      <Alert severity="success" icon={<VerifiedIcon />} sx={{ mb: 2 }}>
        Your company profile is verified — you can apply for green finance and lender programmes.
      </Alert>
    );
  }

  return (
    <Alert severity="warning" sx={{ mb: 2 }}>
      <Stack spacing={1}>
        <Typography variant={compact ? 'body2' : 'subtitle2'} sx={{ fontWeight: 700 }}>
          Verification required for green finance
        </Typography>
        <Typography variant="body2">
          Complete your company profile with valid Udyam, GST, and PAN details. Platform
          administrators verify profiles — you will see status change to Verified when approved.
        </Typography>
        <Button component={RouterLink} to="/msme-profile" size="small" variant="outlined">
          Complete profile
        </Button>
      </Stack>
    </Alert>
  );
};

export default GetVerifiedBanner;
